// Fetch properties ready for scoring
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

try {
  console.log('Fetching properties for deal scoring');

  // In production, fetch properties with complete data from database
  // For demo, generate sample properties
  const properties = [];

  for (let i = 0; i < 30; i++) {
    const capRate = (Math.random() * 5 + 5).toFixed(2); // 5-10%
    const dscr = (Math.random() * 1 + 0.8).toFixed(2); // 0.8-1.8
    const irr = (Math.random() * 10 + 10).toFixed(2); // 10-20%

    properties.push({
      id: `prop-${i}`,
      address: `${1000 + i} ${['Main', 'Oak', 'Elm', 'Pine', 'Maple'][i % 5]} St`,
      city: ['Austin', 'Dallas', 'Houston', 'San Antonio'][i % 4],
      state: 'TX',
      listPrice: Math.floor(Math.random() * 4000000) + 1000000,
      propertyType: ['multifamily', 'retail', 'office', 'industrial'][i % 4],
      squareFeet: Math.floor(Math.random() * 40000) + 10000,
      daysOnMarket: Math.floor(Math.random() * 90) + 1,

      financialModel: {
        capRate: parseFloat(capRate),
        dscr: parseFloat(dscr),
        projectedIRR: parseFloat(irr),
        cashOnCashReturn: (Math.random() * 15 + 5).toFixed(2)
      },

      marketComparables: {
        available: true,
        isPricedBelowMarket: Math.random() > 0.5,
        isCapRateAboveMarket: Math.random() > 0.5,
        priceVsMarket: ((Math.random() * 20 - 10)).toFixed(2) + '%'
      },

      entityResolution: {
        keyPerson: {
          name: `Person ${i}`,
          title: ['CEO', 'Owner', 'Managing Partner'][i % 3]
        }
      },

      contactData: {
        emails: Math.random() > 0.3 ? [{
          email: `person${i}@example.com`,
          status: 'verified'
        }] : [],
        phones: Math.random() > 0.4 ? [{
          number: `+1-512-555-${String(i).padStart(4, '0')}`
        }] : [],
        qualityScore: Math.floor(Math.random() * 60) + 40
      },

      propertyDescription: [
        'Prime location with excellent foot traffic',
        'Recently renovated, turnkey condition',
        'Motivated seller, flexible terms',
        'Strong rental history, stable tenants',
        'Opportunity for value-add improvements'
      ][i % 5]
    });
  }

  return properties.map(prop => ({ json: prop }));

} catch (error) {
  console.error('Error fetching properties:', error.message);
  throw error;
}

// Financial metrics scoring (35% weight)
const property = $input.item.json;
const financials = property.financialModel;

let financialScore = 0;
const financialDetails = [];

// Cap Rate scoring (12%)
if (financials.capRate >= 9) {
  financialScore += 12;
  financialDetails.push({ metric: 'Cap Rate', value: financials.capRate + '%', score: 12, note: 'Excellent' });
} else if (financials.capRate >= 7.5) {
  financialScore += 10;
  financialDetails.push({ metric: 'Cap Rate', value: financials.capRate + '%', score: 10, note: 'Very Good' });
} else if (financials.capRate >= 6.5) {
  financialScore += 7;
  financialDetails.push({ metric: 'Cap Rate', value: financials.capRate + '%', score: 7, note: 'Good' });
} else {
  financialScore += 3;
  financialDetails.push({ metric: 'Cap Rate', value: financials.capRate + '%', score: 3, note: 'Below Target' });
}

// DSCR scoring (10%)
if (financials.dscr >= 1.5) {
  financialScore += 10;
  financialDetails.push({ metric: 'DSCR', value: financials.dscr, score: 10, note: 'Strong' });
} else if (financials.dscr >= 1.25) {
  financialScore += 8;
  financialDetails.push({ metric: 'DSCR', value: financials.dscr, score: 8, note: 'Good' });
} else if (financials.dscr >= 1.0) {
  financialScore += 5;
  financialDetails.push({ metric: 'DSCR', value: financials.dscr, score: 5, note: 'Acceptable' });
} else {
  financialScore += 2;
  financialDetails.push({ metric: 'DSCR', value: financials.dscr, score: 2, note: 'Risky' });
}

// IRR scoring (13%)
if (financials.projectedIRR >= 18) {
  financialScore += 13;
  financialDetails.push({ metric: 'Projected IRR', value: financials.projectedIRR + '%', score: 13, note: 'Excellent' });
} else if (financials.projectedIRR >= 15) {
  financialScore += 11;
  financialDetails.push({ metric: 'Projected IRR', value: financials.projectedIRR + '%', score: 11, note: 'Very Good' });
} else if (financials.projectedIRR >= 12) {
  financialScore += 8;
  financialDetails.push({ metric: 'Projected IRR', value: financials.projectedIRR + '%', score: 8, note: 'Good' });
} else {
  financialScore += 4;
  financialDetails.push({ metric: 'Projected IRR', value: financials.projectedIRR + '%', score: 4, note: 'Below Target' });
}

console.log(`Financial score for ${property.address}: ${financialScore}/35`);

return [{
  json: {
    ...property,
    scoring: {
      financial: {
        score: financialScore,
        maxScore: 35,
        details: financialDetails
      }
    }
  }
}];

// Location quality scoring (25% weight)
const property = $input.item.json;

let locationScore = 0;
const locationDetails = [];

// City tier scoring
const cityTiers = {
  'Austin': { score: 25, tier: 'Tier 1', growth: 'High' },
  'Dallas': { score: 23, tier: 'Tier 1', growth: 'High' },
  'Houston': { score: 22, tier: 'Tier 1', growth: 'Medium-High' },
  'San Antonio': { score: 20, tier: 'Tier 2', growth: 'Medium' }
};

const cityData = cityTiers[property.city] || { score: 15, tier: 'Tier 3', growth: 'Medium' };
locationScore = cityData.score;

locationDetails.push({
  metric: 'City Quality',
  value: property.city,
  score: cityData.score,
  note: `${cityData.tier}, ${cityData.growth} Growth`
});

// Property type demand bonus
const propertyTypeDemand = {
  'multifamily': 5,
  'industrial': 4,
  'retail': 3,
  'office': 2
};

const typeBonus = propertyTypeDemand[property.propertyType] || 2;
if (typeBonus > 0) {
  locationDetails.push({
    metric: 'Property Type Demand',
    value: property.propertyType,
    bonus: typeBonus,
    note: typeBonus >= 4 ? 'High Demand' : 'Moderate Demand'
  });
}

console.log(`Location score for ${property.city}: ${locationScore}/25`);

return [{
  json: {
    ...property,
    scoring: {
      ...property.scoring,
      location: {
        score: locationScore,
        maxScore: 25,
        details: locationDetails
      }
    }
  }
}];

// Owner motivation scoring (20% weight)
const property = $input.item.json;

let motivationScore = 0;
const motivationDetails = [];

// Days on market
if (property.daysOnMarket > 90) {
  motivationScore += 12;
  motivationDetails.push({ metric: 'Days on Market', value: property.daysOnMarket, score: 12, note: 'High Motivation' });
} else if (property.daysOnMarket > 60) {
  motivationScore += 10;
  motivationDetails.push({ metric: 'Days on Market', value: property.daysOnMarket, score: 10, note: 'Good Motivation' });
} else if (property.daysOnMarket > 30) {
  motivationScore += 7;
  motivationDetails.push({ metric: 'Days on Market', value: property.daysOnMarket, score: 7, note: 'Moderate' });
} else {
  motivationScore += 4;
  motivationDetails.push({ metric: 'Days on Market', value: property.daysOnMarket, score: 4, note: 'New Listing' });
}

// Market positioning
if (property.marketComparables?.isPricedBelowMarket) {
  motivationScore += 8;
  motivationDetails.push({ metric: 'Pricing', value: property.marketComparables.priceVsMarket, score: 8, note: 'Below Market' });
} else {
  motivationScore += 3;
  motivationDetails.push({ metric: 'Pricing', value: property.marketComparables.priceVsMarket, score: 3, note: 'Market Rate' });
}

console.log(`Motivation score: ${motivationScore}/20`);

return [{
  json: {
    ...property,
    scoring: {
      ...property.scoring,
      motivation: {
        score: motivationScore,
        maxScore: 20,
        details: motivationDetails
      }
    }
  }
}];

// Contact quality scoring (10% weight)
const property = $input.item.json;
const contacts = property.contactData;

let contactScore = 0;
const contactDetails = [];

// Email availability and verification
if (contacts.emails?.length > 0) {
  const email = contacts.emails[0];
  if (email.status === 'verified') {
    contactScore += 6;
    contactDetails.push({ metric: 'Email', value: 'Verified', score: 6, note: 'Direct contact available' });
  } else {
    contactScore += 3;
    contactDetails.push({ metric: 'Email', value: 'Unverified', score: 3, note: 'Needs verification' });
  }
} else {
  contactDetails.push({ metric: 'Email', value: 'None', score: 0, note: 'No email found' });
}

// Phone availability
if (contacts.phones?.length > 0) {
  contactScore += 4;
  contactDetails.push({ metric: 'Phone', value: 'Available', score: 4, note: 'Phone contact available' });
} else {
  contactDetails.push({ metric: 'Phone', value: 'None', score: 0, note: 'No phone found' });
}

console.log(`Contact score: ${contactScore}/10`);

return [{
  json: {
    ...property,
    scoring: {
      ...property.scoring,
      contact: {
        score: contactScore,
        maxScore: 10,
        details: contactDetails
      }
    }
  }
}];

// Market timing scoring (10% weight)
const property = $input.item.json;

let timingScore = 0;
const timingDetails = [];

// Simulated market cycle analysis
const marketCycle = ['Early Growth', 'Peak', 'Late Cycle', 'Correction'][Math.floor(Math.random() * 4)];

const cycleScoring = {
  'Early Growth': { score: 10, note: 'Optimal buying opportunity' },
  'Peak': { score: 6, note: 'Be cautious, prices at high' },
  'Late Cycle': { score: 8, note: 'Good time for value plays' },
  'Correction': { score: 9, note: 'Excellent buying conditions' }
};

const cycleData = cycleScoring[marketCycle];
timingScore = cycleData.score;

timingDetails.push({
  metric: 'Market Cycle',
  value: marketCycle,
  score: cycleData.score,
  note: cycleData.note
});

console.log(`Market timing score: ${timingScore}/10`);

return [{
  json: {
    ...property,
    scoring: {
      ...property.scoring,
      timing: {
        score: timingScore,
        maxScore: 10,
        details: timingDetails,
        marketCycle: marketCycle
      }
    }
  }
}];

// GPT-4 property analysis (qualitative enhancement)
const property = $input.item.json;

// In production, call OpenAI GPT-4 API
// For demo, simulate AI analysis

const description = property.propertyDescription;

// Simulated GPT-4 analysis
const aiAnalysis = {
  sentiment: Math.random() > 0.3 ? 'positive' : 'neutral',
  opportunityKeywords: [],
  riskFactors: [],
  summary: '',
  investmentThesis: '',
  scoreAdjustment: 0
};

// Keyword detection
const positiveKeywords = ['prime', 'excellent', 'renovated', 'motivated', 'strong', 'stable', 'opportunity', 'turnkey'];
const riskKeywords = ['needs work', 'deferred maintenance', 'challenging', 'uncertain'];

positiveKeywords.forEach(keyword => {
  if (description.toLowerCase().includes(keyword)) {
    aiAnalysis.opportunityKeywords.push(keyword);
    aiAnalysis.scoreAdjustment += 0.5;
  }
});

riskKeywords.forEach(keyword => {
  if (description.toLowerCase().includes(keyword)) {
    aiAnalysis.riskFactors.push(keyword);
    aiAnalysis.scoreAdjustment -= 1;
  }
});

aiAnalysis.summary = `${property.propertyType} property in ${property.city} with ${aiAnalysis.opportunityKeywords.length} positive indicators.`;

aiAnalysis.investmentThesis = aiAnalysis.sentiment === 'positive' 
  ? 'Strong investment opportunity based on financials and market position.'
  : 'Moderate opportunity, requires further due diligence.';

console.log(`AI Analysis: ${aiAnalysis.sentiment}, Score adjustment: ${aiAnalysis.scoreAdjustment}`);

return [{
  json: {
    ...property,
    aiAnalysis: aiAnalysis
  }
}];

// Calculate final deal score
const property = $input.item.json;
const scoring = property.scoring;
const aiAnalysis = property.aiAnalysis;

// Sum all component scores
const totalScore = 
  scoring.financial.score +
  scoring.location.score +
  scoring.motivation.score +
  scoring.contact.score +
  scoring.timing.score +
  aiAnalysis.scoreAdjustment;

// Maximum possible score: 100
const maxScore = 100;
const finalScore = Math.min(Math.max(Math.round(totalScore), 0), 100);

// Determine deal tier
let dealTier = 'D';
let tierDescription = '';
let action = '';

if (finalScore >= 85) {
  dealTier = 'S';
  tierDescription = 'Exceptional Deal';
  action = 'IMMEDIATE ACTION REQUIRED';
} else if (finalScore >= 75) {
  dealTier = 'A';
  tierDescription = 'Excellent Deal';
  action = 'High Priority - Review Today';
} else if (finalScore >= 65) {
  dealTier = 'B';
  tierDescription = 'Good Deal';
  action = 'Review This Week';
} else if (finalScore >= 50) {
  dealTier = 'C';
  tierDescription = 'Fair Deal';
  action = 'Monitor for Changes';
} else {
  dealTier = 'D';
  tierDescription = 'Below Threshold';
  action = 'Low Priority';
}

// Investment recommendation
let recommendation = '';
if (finalScore >= 85) {
  recommendation = 'STRONG BUY - Initiate contact immediately and prepare offer.';
} else if (finalScore >= 75) {
  recommendation = 'BUY - Schedule property tour and begin due diligence.';
} else if (finalScore >= 65) {
  recommendation = 'CONSIDER - Conduct further analysis, evaluate against alternatives.';
} else if (finalScore >= 50) {
  recommendation = 'WATCH - Monitor for price reductions or market changes.';
} else {
  recommendation = 'PASS - Does not meet investment criteria at this time.';
}

const finalDealScore = {
  propertyId: property.id,
  address: property.address,
  city: property.city,
  listPrice: property.listPrice,
  propertyType: property.propertyType,

  // Scoring breakdown
  scoreBreakdown: {
    financial: scoring.financial.score,
    location: scoring.location.score,
    motivation: scoring.motivation.score,
    contact: scoring.contact.score,
    timing: scoring.timing.score,
    aiAdjustment: aiAnalysis.scoreAdjustment,
    total: finalScore
  },

  // Final assessment
  finalScore: finalScore,
  maxScore: maxScore,
  dealTier: dealTier,
  tierDescription: tierDescription,
  recommendation: recommendation,
  action: action,

  // Highlights
  topStrengths: [
    ...scoring.financial.details.filter(d => d.score >= 10).map(d => `${d.metric}: ${d.note}`),
    ...scoring.location.details.filter(d => d.score >= 20).map(d => `${d.metric}: ${d.note}`),
    ...(aiAnalysis.opportunityKeywords.length > 2 ? ['Strong property description indicators'] : [])
  ].slice(0, 3),

  concerns: [
    ...scoring.financial.details.filter(d => d.score < 8).map(d => `${d.metric}: ${d.note}`),
    ...scoring.contact.details.filter(d => d.score === 0).map(d => `${d.metric}: ${d.note}`),
    ...aiAnalysis.riskFactors.map(r => `Risk flag: ${r}`)
  ].slice(0, 3),

  // Full property data
  propertyData: property,
  scoredAt: new Date().toISOString()
};

console.log(`Final Score: ${finalScore}/100 - Tier ${dealTier} - ${tierDescription}`);

return [{ json: finalDealScore }];

// Sort and rank deals
const deals = $input.all().map(item => item.json);

// Sort by final score (descending)
deals.sort((a, b) => b.finalScore - a.finalScore);

// Add rank
deals.forEach((deal, index) => {
  deal.rank = index + 1;
});

const summary = {
  totalDeals: deals.length,
  tierBreakdown: {
    S: deals.filter(d => d.dealTier === 'S').length,
    A: deals.filter(d => d.dealTier === 'A').length,
    B: deals.filter(d => d.dealTier === 'B').length,
    C: deals.filter(d => d.dealTier === 'C').length,
    D: deals.filter(d => d.dealTier === 'D').length
  },
  averageScore: (deals.reduce((sum, d) => sum + d.finalScore, 0) / deals.length).toFixed(2),
  topDeals: deals.filter(d => d.finalScore >= 85),
  actionRequired: deals.filter(d => d.finalScore >= 75)
};

console.log(`Scored ${deals.length} deals. ${summary.topDeals.length} S-tier, ${summary.actionRequired.length} require action.`);

return [{
  json: {
    summary: summary,
    rankedDeals: deals,
    timestamp: new Date().toISOString()
  }
}];

// Save scored deals to database
const data = $input.first().json;

console.log(`[DATABASE] Saving ${data.rankedDeals.length} scored deals`);

// In production, write to database

const result = {
  success: true,
  dealsSaved: data.rankedDeals.length,
  summary: data.summary,
  timestamp: new Date().toISOString(),
  nextStep: 'delivery-layer'
};

return [{ json: result }];
